public class LoopCycleDetectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void finish() {
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }

    public static void main(String[] args) {
        check("a three-line loop", "[7, 8, 9]",
                String.valueOf(LoopCycleDetector.repeatingCycle(new int[]{4, 7, 8, 9, 7, 8, 9, 7, 8, 9})));
        check("a two-line loop", "[1, 2]",
                String.valueOf(LoopCycleDetector.repeatingCycle(new int[]{1, 2, 1, 2, 1, 2})));
        check("a single line spinning", "[5]",
                String.valueOf(LoopCycleDetector.repeatingCycle(new int[]{9, 5, 5, 5})));
        check("progress means no cycle", "[]",
                String.valueOf(LoopCycleDetector.repeatingCycle(new int[]{1, 2, 3, 4})));
        check("only two repetitions is not enough", "[]",
                String.valueOf(LoopCycleDetector.repeatingCycle(new int[]{1, 2, 1, 2})));
        check("an empty trace", "[]",
                String.valueOf(LoopCycleDetector.repeatingCycle(new int[]{})));
        check("the smallest k wins", "[3]",
                String.valueOf(LoopCycleDetector.repeatingCycle(new int[]{3, 3, 3, 3, 3, 3})));
        check("only the tail matters", "[2, 3]",
                String.valueOf(LoopCycleDetector.repeatingCycle(new int[]{8, 8, 2, 3, 2, 3, 2, 3})));
        check("isSuspicious true", true,
                LoopCycleDetector.isSuspicious(new int[]{7, 8, 7, 8, 7, 8}));
        check("isSuspicious false", false,
                LoopCycleDetector.isSuspicious(new int[]{1, 2, 3, 4, 5, 6}));
        finish();
    }
}

