public class LoopCycleDetector {

    public static java.util.List<Integer> repeatingCycle(int[] executed) {
        int n = executed.length;
        for (int k = 1; k <= n / 3; k++) {
            if (repeatsThreeTimes(executed, k)) {
                java.util.List<Integer> cycle = new java.util.ArrayList<>();
                for (int i = n - k; i < n; i++) {
                    cycle.add(executed[i]);
                }
                return cycle;
            }
        }
        return new java.util.ArrayList<>();
    }

    public static boolean isSuspicious(int[] executed) {
        return !repeatingCycle(executed).isEmpty();
    }

    private static boolean repeatsThreeTimes(int[] executed, int k) {
        int start = executed.length - 3 * k;
        for (int i = 0; i < 2 * k; i++) {
            if (executed[start + i] != executed[start + i + k]) {
                return false;
            }
        }
        return true;
    }
}
